patch:
diff --git a/repro-no-loss-of-precision.js b/repro-no-loss-of-precision.js
new file mode 100644
index 0000000..ed66505
--- /dev/null
+++ b/repro-no-loss-of-precision.js
@@ -0,0 +1,33 @@
+"use strict";
+
+// Check for the report "no-loss-of-precision rule incorrectly flags 9.000e+3".
+// Exits non-zero while the rule reports these literals, zero once it does not.
+
+const assert = require("node:assert/strict");
+const { Linter } = require("./lib/api");
+
+const linter = new Linter();
+const config = [{ rules: { "no-loss-of-precision": "error" } }];
+
+// 9000 is exactly representable, so none of these should be reported.
+const literals = ["9.000e+3", "9.000e3", "9.0000e4", "9.000e4", "9.0000e5"];
+
+let failed = 0;
+
+for (const literal of literals) {
+	const messages = linter.verify(`const test = ${literal};`, config);
+
+	try {
+		assert.deepEqual(
+			messages.map(message => message.message),
+			[],
+			`${literal} (value ${Number(literal)}) must not lose precision`,
+		);
+		console.log(`ok     ${literal}`);
+	} catch (error) {
+		failed++;
+		console.log(`FAILED ${literal}: ${messages.map(message => message.message).join("; ")}`);
+	}
+}
+
+assert.equal(failed, 0, `${failed} of ${literals.length} literals were wrongly reported`);
